/**
 * dsh-mcp-manager — mcpServers JSON 导入（独立模块）。
 *
 * 把 mcpServers JSON 条目（{ serverName: config }，业界通用格式）映射为
 * 插件服务器配置：解析粘贴的 JSON 文本，供 /api/dsh-mcp/import/json
 * 使用。仅支持 JSON 文本导入（不扫描任何应用的配置文件）。
 * 由 lib/index.js 组合根 re-export。
 */

import type { ServerConfig } from "./types.ts";

// ------------------------------------------- mcpServers JSON 条目映射

/** 把一条 mcpServers JSON 条目映射为服务器配置。 */
export function fromClaudeEntry(name: string, entry: Record<string, unknown>): ServerConfig {
  const type = entry.type;
  if (type === "http" || type === "sse" || entry.url !== undefined) {
    if (typeof entry.url !== "string" || entry.url === "") throw new Error(`server "${name}": missing url`);
    const server: ServerConfig = {
      name,
      transport: "streamable-http",
      url: entry.url,
    };
    if (typeof entry.headers === "object" && entry.headers !== null) server.headers = entry.headers as Record<string, string>;
    if (typeof entry.env === "object" && entry.env !== null && Object.keys(entry.env).length > 0) {
      // http 传输不支持 env，合并进 headers 之外忽略——记录来源即可
      server.sourceEnv = Object.keys(entry.env);
    }
    return server;
  }
  if (typeof entry.command !== "string" || entry.command === "") {
    throw new Error(`server "${name}": unsupported entry (need command or url)`);
  }
  const server: ServerConfig = {
    name,
    transport: "stdio",
    command: entry.command,
  };
  if (Array.isArray(entry.args)) server.args = entry.args.map(String);
  if (typeof entry.cwd === "string" && entry.cwd !== "") server.cwd = entry.cwd;
  if (typeof entry.env === "object" && entry.env !== null) {
    server.env = Object.fromEntries(Object.entries(entry.env).map(([key, value]) => [key, String(value)]));
  }
  return server;
}

/** 解析一段 mcpServers JSON 文本为配置列表。 */
export function parseClaudeJson(text: string): ServerConfig[] {
  const parsed = JSON.parse(text);
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("JSON must be an object of { serverName: config }");
  }
  return Object.entries(parsed as Record<string, unknown>).map(([name, entry]) => {
    if (typeof entry !== "object" || entry === null) throw new Error(`server "${name}": entry must be an object`);
    return fromClaudeEntry(name, entry as Record<string, unknown>);
  });
}

packages/dsh-mcp-manager/src/normalize.t.source:
/**
 * dsh-mcp-manager — 服务器配置归一化（纯函数，单一事实源）。
 *
 * normalizeServer 校验并规范化一条 MCP 服务器配置（stdio / streamable-http），
 * 供 Manager 增改与 mcpServers JSON 导入路径共用；SERVER_NAME_PATTERN 为
 * 服务器名命名空间约束（与官方 dsh-mcp-client 一致）。
 */

import type { ServerConfig } from "./types.ts";
import { DEFAULT_TOOL_CALL_TIMEOUT_MS } from "./supervisor.ts";

/** MCP 服务器名命名空间约束（与官方 dsh-mcp-client 一致）。 */
export const SERVER_NAME_PATTERN = /^[A-Za-z0-9_-]{1,32}$/;

/** 校验并规范化一条服务器配置。 */
export function normalizeServer(input: unknown): ServerConfig {
  if (typeof input !== "object" || input === null) throw new Error("server config must be an object");
  const src = input as Record<string, unknown>;
  const name = String(src.name ?? "").trim();
  if (!SERVER_NAME_PATTERN.test(name)) {
    throw new Error(`server name must match ${SERVER_NAME_PATTERN.source}`);
  }
  const transport = src.transport === "streamable-http" ? "streamable-http" : src.transport === "stdio" ? "stdio" : undefined;
  if (transport === undefined) throw new Error('transport must be "stdio" or "streamable-http"');
  if (transport === "stdio") {
    if (typeof src.command !== "string" || (src.command as string).trim() === "") {
      throw new Error("stdio server requires a command");
    }
  } else {
    if (typeof src.url !== "string" || (src.url as string).trim() === "") {
      throw new Error("streamable-http server requires a url");
    }
    try {
      new URL(src.url as string);
    } catch {
      throw new Error(`invalid url: ${src.url}`);
    }
  }
  const server: ServerConfig = {
    name,
    transport,
    enabled: src.enabled !== false,
    toolCallTimeoutMs: typeof src.toolCallTimeoutMs === "number" && (src.toolCallTimeoutMs as number) > 0
      ? Math.floor(src.toolCallTimeoutMs as number)
      : DEFAULT_TOOL_CALL_TIMEOUT_MS,
    reconnect: (src.reconnect as Record<string, unknown> | undefined) ?? {},
    // 能力目录的自定义描述（用户手写；MCP 协议无服务器级自描述，完整保留不截断）。
    description: typeof src.description === "string" && (src.description as string).trim() !== ""
      ? (src.description as string).trim()
      : undefined,
  };
  if (transport === "stdio") {
    server.command = src.command as string;
    if (Array.isArray(src.args)) server.args = (src.args as unknown[]).map(String);
    if (typeof src.cwd === "string" && (src.cwd as string) !== "") server.cwd = src.cwd as string;
    if (typeof src.env === "object" && src.env !== null) {
      server.env = Object.fromEntries(Object.entries(src.env as Record<string, unknown>).map(([key, value]) => [key, String(value)]));
    }
  } else {
    server.url = src.url as string;
    if (typeof src.headers === "object" && src.headers !== null) {
      server.headers = Object.fromEntries(Object.entries(src.headers as Record<string, unknown>).map(([key, value]) => [key, String(value)]));
    }
  }
  return server;
}

packages/dsh-mcp-manager/src/placement-m.source:
/**
 * dsh-mcp-manager — 浮窗定位/层级/断点纯函数（#128 移动端适配）。
 *
 * 单一事实源：宿主端（src/index.ts）re-export 供 smoke 断言；客户端（src/client/*）
 * 直接 import 同一份实现打进 browser bundle。本文件必须保持零依赖（禁止 import
 * 任何 node:* 模块），否则会污染 client 产物。
 *
 * 跨包约定（与 dsh-provider-usage 同构）：断点档位阈值、zIndex 值域与派生量、
 * safe-area 视口 clamp 语义见 docs/DEVELOPMENT.md「浮窗移动端适配约定」。
 */

// ---- z-index 层级基准 ------------------------------------------------------

/** 层级基准值域下界。 */
export const Z_INDEX_BASE_MIN = 1;
/** 层级基准值域上界（避开宿主 shell 的模态/遮罩层）。 */
export const Z_INDEX_BASE_MAX = 9000;
/** 下拉面板相对胶囊的层级派生量（胶囊 base、面板 base+30，保证面板盖住自身胶囊）。 */
export const Z_INDEX_PANEL_DELTA = 30;

/** 默认层级基准（mcp-manager 包：对应 CSS 默认 z-index:10，升级前行为不回归）。 */
export const DEFAULT_Z_INDEX_BASE = 10;

/**
 * 层级基准 clamp 纯函数（供 smoke 断言边界）：非有限数回退默认；
 * 有限数四舍五入后压进 [Z_INDEX_BASE_MIN, Z_INDEX_BASE_MAX]。
 */
export function clampZIndexBase(value: unknown, dflt: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return dflt;
  return Math.min(Z_INDEX_BASE_MAX, Math.max(Z_INDEX_BASE_MIN, Math.round(value)));
}

/** 面板层级派生纯函数：面板 z-index = 胶囊基准 + 30。 */
export function panelZIndexFor(base: number): number {
  return clampZIndexBase(base, DEFAULT_Z_INDEX_BASE) + Z_INDEX_PANEL_DELTA;
}

/** 面板垂直锚点规则：底部锚点（bottom-*）→ 向上弹出；否则顶部锚点（向下弹出）。 */
export function panelAnchorForPosition(position: string | undefined): "top" | "bottom" {
  return position === "bottom-right" || position === "bottom-left" ? "bottom" : "top";
}

// ---- 断点档位（#128）-------------------------------------------------------

// 判定基准 = conversationHost rect 宽度（JS 判定 + data 属性切换样式），非纯
// @media——防桌面窄窗 / iPad Slide Over 误触发（规格 #128 第 3 条）。

/** 窄屏档上界（手机竖屏 / 极窄分栏）。 */
export const BREAKPOINT_NARROW_MAX = 480;
/** 平板档上界（平板竖屏 / 手机横屏；超过即桌面档）。 */
export const BREAKPOINT_TABLET_MAX = 834;

export type FloatBreakpoint = "narrow" | "tablet" | "wide";

/** 断点判定纯函数（供 smoke 断言分支翻转）：按会话容器宽度返回档位。 */
export function breakpointForWidth(width: number): FloatBreakpoint {
  const w = Number.isFinite(width) ? width : Number.POSITIVE_INFINITY;
  if (w <= BREAKPOINT_NARROW_MAX) return "narrow";
  if (w <= BREAKPOINT_TABLET_MAX) return "tablet";
  return "wide";
}

// ---- 终坐标视口 clamp（safe-area 语义，规格 #128 第 1 条）-------------------

/** 视口坐标点（fixed 元素最终 left/top）。 */
export interface ViewportPoint { x: number; y: number; }

/**
 * 终坐标视口 clamp 纯函数（供 smoke 断言）：对算好的 fixed 坐标做钳制，保证元素
 * 完整落在 [safeInset, viewport - size - safeInset] 内。宿主 viewport meta 无
 * viewport-fit=cover → env(safe-area-inset-*) 恒 0 → safeInset 缺省 0 时本函数
 * 自然退化为普通视口 clamp（现状行为不回归）；未来宿主若开启 cover 可传实测 inset。
 */
export function clampPointToViewport(
  x: number,
  y: number,
  width: number,
  height: number,
  viewportW: number,
  viewportH: number,
  safeInset: number = 0,
): ViewportPoint {
  const ins = Number.isFinite(safeInset) ? Math.max(0, safeInset) : 0;
  const hiX = Math.max(ins, viewportW - width - ins);
  const hiY = Math.max(ins, viewportH - height - ins);
  return {
    x: Math.min(Math.max(x, ins), hiX),
    y: Math.min(Math.max(y, ins), hiY),
  };
}

packages/dsh-mcp-manager/src/protocol.ts.source:
/**
 * dsh-mcp-manager — MCP 协议客户端（独立模块）。
 *
 * 协议能力面（initialize 版本协商、notifications/initialized、请求超时与
 * 取消、JSON-RPC 帧构造）由官方 @modelcontextprotocol/sdk 的 Client 承担
 * （issue #11，决策 #47 approved；devDependency，构建期内联进产物）。
 * 本类仅做薄适配，保持 supervisor 的既有调用面不变：
 *   new MCPClient(transport) → initialize() → listTools(cursor) / callTool(...)。
 * 由 lib/index.js 组合根 re-export。
 */

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { ListToolsResultSchema, ResultSchema } from "@modelcontextprotocol/sdk/types.js";
import type { StdioTransport, HttpTransport } from "./transport.ts";

/**
 * MCP 客户端适配器：包装官方 SDK Client。
 *
 * schema 选择（契约不漂移，PoC 关键决策）：
 *  - listTools 走 Protocol.request + 官方 ListToolsResultSchema：享受协议层
 *    响应校验；刻意**绕过** Client.listTools()——后者会缓存工具 outputSchema
 *    校验器并在 callTool 时强校验 structuredContent（缺失即抛错），会改变
 *    自写版"结果原样投影给 dsh 工具系统（未知 content 类型降级占位符）"
 *    的行为语义；
 *  - callTool 显式传宽松 ResultSchema：结果 JSON 原样透传（isError /
 *    structuredContent 判定由 supervisor.buildToolDefinition 承担，与自写版一致）。
 */
export class MCPClient {
  transport: StdioTransport | HttpTransport;
  client: Client | undefined;

  constructor(transport: StdioTransport | HttpTransport) {
    this.transport = transport;
  }

  /**
   * 建立 MCP 会话：SDK Client.connect 完成 initialize 版本协商 +
   * notifications/initialized（替代自写版的硬编码 protocolVersion 2025-03-26）。
   */
  async initialize(): Promise<unknown> {
    const client = new Client({ name: "dsh-mcp-manager", version: "0.1.0" }, { capabilities: {} });
    try {
      await client.connect(this.transport.sdk);
    } catch (error) {
      // stdio 启动失败时附 stderr 尾巴（自写版诊断语义：npx 拉包失败等
      // 场景的 stderr 是唯一线索）。
      const tail = (this.transport as StdioTransport).stderrTail?.trim();
      if (typeof tail === "string" && tail !== "") {
        throw new Error(`${error instanceof Error ? error.message : String(error)} (stderr: ${tail})`);
      }
      throw error;
    }
    this.client = client;
    return client.getServerVersion();
  }

  /** tools/list（分页游标透传）。 */
  async listTools(cursor?: string) {
    const client = this.requireClient();
    return client.request(
      { method: "tools/list", params: cursor === undefined ? {} : { cursor } },
      ListToolsResultSchema,
    );
  }

  /** tools/call（signal/timeoutMs 透传为 SDK RequestOptions）。
   * 走 Protocol.request + 宽松 ResultSchema：结果 JSON 原样透传给调用方
   * （isError / structuredContent 判定由 supervisor.buildToolDefinition 承担，
   * 与自写版一致；不用 Client.callTool 以避开其 outputSchema 运行时强校验
   * 与 task-required 门禁带来的行为漂移）。 */
  async callTool(rawName: string, args?: unknown, opts?: { signal?: AbortSignal; timeoutMs?: number }) {
    const client = this.requireClient();
    // arguments 按规范仅接受 object；非对象入参省略该键（supervisor 实际只传对象）。
    const params: { name: string; arguments?: Record<string, unknown> } = { name: rawName };
    if (typeof args === "object" && args !== null) params.arguments = args as Record<string, unknown>;
    return client.request({ method: "tools/call", params }, ResultSchema, {
      signal: opts?.signal,
      timeout: opts?.timeoutMs,
    });
  }

  requireClient(): Client {
    if (this.client === undefined) {
      throw new Error("MCP client is not initialized (call initialize first)");
    }
    return this.client;
  }
}

