  assert.equal(normalizeUiConfig({ zIndexBase: "x" }).zIndexBase, DEFAULT_UI_CONFIG.zIndexBase, "非数字回退默认");
  assert.equal(panelZIndexFor(10), 40, "面板层级派生 base+30");
