  assert.equal(breakpointForWidth(BREAKPOINT_TABLET_MAX + 1), "wide", "835 翻转 wide");
  assert.equal(breakpointForWidth(Number.NaN), "wide", "异常宽度按宽档兜底");
  const clampedPoint = clampPointToViewport(-30, -50, 100, 80, 375, 667);
